<template><main class="flow-page"><section class="flow-card"><div class="status-icon">⌛</div><h1>身份审核进度</h1><p class="hint">管理员通常会在 1–3 个工作日内完成审核。结果更新后，请重新登录进入对应工作台。</p><div v-if="applications.length" class="applications"><article v-for="item in applications" :key="item.id"><div><strong>{{ roleName[item.role] || item.role }}</strong><p>{{ item.organization_name }}</p></div><span :class="['tag', item.status]">{{ statusName[item.status] || item.status }}</span><p v-if="item.review_note" class="note">审核说明：{{ item.review_note }}</p></article></div><p v-else class="empty">暂无身份申请</p><div class="actions"><RouterLink class="btn" to="/identity/apply">提交新申请</RouterLink><RouterLink class="btn btn-primary" to="/overview">返回学生空间</RouterLink></div></section></main></template>
<script setup>
import { onMounted, ref } from 'vue';import { authApi } from '@/api/auth'
const props=defineProps({initialApplications:{type:Array,default:()=>[]}});const applications=ref([...props.initialApplications]);const roleName={teacher:'教师',researcher:'科研人员'},statusName={pending:'审核中',needs_more_info:'待补充材料',approved:'已通过',rejected:'未通过'}
onMounted(async()=>{if(!applications.value.length){try{applications.value=await authApi.currentRoleApplications()}catch{/* page keeps empty state */}}})
</script>
<style scoped>.flow-page{min-height:100vh;display:grid;place-items:center;padding:24px;background:var(--bg)}.flow-card{width:min(680px,100%);background:white;border:1px solid var(--line);border-radius:22px;padding:38px;box-shadow:var(--shadow-md)}.status-icon{font-size:34px}.hint{color:var(--ink2);margin:8px 0 24px}.applications{display:grid;gap:12px}.applications article{display:grid;grid-template-columns:1fr auto;padding:16px;border:1px solid var(--line);border-radius:14px}.applications p{color:var(--ink2);font-size:13px}.note{grid-column:1/-1;margin-top:8px}.tag.pending{background:var(--warn-bg);color:var(--warn-deep)}.tag.approved{background:var(--ok-bg);color:var(--ok-deep)}.tag.rejected{background:var(--err-bg);color:var(--err-deep)}.actions{display:flex;justify-content:flex-end;gap:10px;margin-top:24px}.empty{color:var(--ink3);padding:24px;text-align:center}</style>
